14	)
15	
16	func tempDir(t *testing.T) string {
17		t.Helper()
18		dir := t.TempDir()
19		return filepath.Join(dir, "store")
20	}
21	
22	func openStore(t *testing.T, dir string) *Store {
23		t.Helper()
24		s, err := Open(dir)
25		if err != nil {
26			t.Fatalf("Open: %v", err)
