28		t.Cleanup(func() { s.Close() })
29		return s
30	}
31	
32	func TestBasicCRUD(t *testing.T) {
33		s := openStore(t, tempDir(t))
34	
35		if got, ok, err := s.Get("missing"); ok || err != nil || got != nil {
36			t.Fatalf("missing key: got=%q ok=%v err=%v", got, ok, err)
37		}
38		if err := s.Put("a", []byte("one")); err != nil {
39			t.Fatal(err)
40		}
41		if got, ok, err := s.Get("a"); !ok || err != nil || string(got) != "one" {
42			t.Fatalf("get a: got=%q ok=%v err=%v", got, ok, err)
43		}
44		if err := s.Put("a", []byte("two")); err != nil {
45			t.Fatal(err)
46		}
47		if got, ok, _ := s.Get("a"); !ok || string(got) != "two" {
48			t.Fatalf("overwritten a: got=%q ok=%v", got, ok)
49		}
50		if err := s.Delete("a"); err != nil {
51			t.Fatal(err)
52		}
53		if _, ok, err := s.Get("a"); ok || err != nil {
54			t.Fatalf("deleted a: ok=%v err=%v", ok, err)
55		}
56		// Idempotent deletes: missing and already-deleted keys return nil.
57		if err := s.Delete("a"); err != nil {
58			t.Fatalf("repeat delete: %v", err)
59		}
60		if err := s.Delete("never-existed"); err != nil {
61			t.Fatalf("delete missing: %v", err)
62		}
63	}
64	
65	func TestEmptyKeyAndEmptyValues(t *testing.T) {
66		s := openStore(t, tempDir(t))
