108		}
109	
110		// Committed after the snapshot: invisible to it.
111		mustPut("old", "v2")                     // overwritten old value stays readable
112		mustPut("brand-new", "n")                // new key is a miss
113		if err := s.Delete("gone"); err != nil { // deleted value stays readable
114			t.Fatal(err)
115		}
116	
117		if got, ok := snap.Get("old"); !ok || string(got) != "v1" {
118			t.Fatalf("snap old: %q %v", got, ok)
119		}
120		if got, ok := snap.Get("gone"); !ok || string(got) != "x" {
121			t.Fatalf("snap gone: %q %v", got, ok)
122		}
123		if _, ok := snap.Get("brand-new"); ok {
124			t.Fatal("snap sees key created after it")
125		}
126		if _, ok := snap.Get("never"); ok {
127			t.Fatal("snap hit on unknown key")
128		}
129		if _, ok := snap.Get(""); ok {
130			t.Fatal("snap hit on empty key")
131		}
132	
133		// The live store sees the new view.
134		if got, ok, _ := s.Get("old"); !ok || string(got) != "v2" {
135			t.Fatalf("live old: %q %v", got, ok)
136		}
137		if _, ok, _ := s.Get("gone"); ok {
138			t.Fatal("live store still sees deleted key")
139		}
140	
141		// A second snapshot catches the current state.
142		snap2, err := s.Snapshot()
143		if err != nil {
144			t.Fatal(err)
145		}
146		if _, ok := snap2.Get("gone"); ok {
147			t.Fatal("new snapshot sees deleted key")
148		}
149		if got, ok := snap2.Get("brand-new"); !ok || string(got) != "n" {
150			t.Fatalf("new snapshot brand-new: %q %v", got, ok)
151		}
152		snap2.Close()
153	
154		// Closing the snapshot turns every read into a miss, without error.
155		if err := snap.Close(); err != nil {
156			t.Fatal(err)
157		}
158		if _, ok := snap.Get("old"); ok {
159			t.Fatal("closed snapshot reported hit")
160		}
161		if err := snap.Close(); err != nil {
162			t.Fatalf("double snapshot close: %v", err)
163		}
164	}
