551	func TestConcurrentSnapshotClose(t *testing.T) {
552		s := openStore(t, tempDir(t))
553		for _, k := range []string{"a", "b", "c"} {
554			if err := s.Put(k, []byte("0")); err != nil {
555				t.Fatal(err)
556			}
557		}
558	
559		const readers = 8
560		var readerWg sync.WaitGroup
561		var sawClosed atomic.Int64
562		for r := 0; r < readers; r++ {
563			readerWg.Add(1)
564			go func() {
565				defer readerWg.Done()
566				for {
567					snap, err := s.Snapshot()
568					if err != nil {
569						if errors.Is(err, fs.ErrClosed) {
570							sawClosed.Add(1)
571							return
572						}
573						t.Errorf("snapshot err: %v", err)
574						return
575					}
576					// The fixed view must be internally consistent: two full
577					// passes over the keys return identical bytes, each value a
578					// well-formed decimal marker.
579					first := map[string][]byte{}
580					for _, k := range []string{"a", "b", "c"} {
581						v, ok := snap.Get(k)
582						if !ok {
583							t.Error("initial key missing in snapshot")
584							break
585						}
586						if n, err := strconv.Atoi(string(v)); err != nil || n < 0 {
587							t.Errorf("malformed value %q", v)
588							break
589						}
590						first[k] = v
591					}
592					for k, want := range first {
593						if got, ok := snap.Get(k); !ok || !bytes.Equal(got, want) {
594							t.Error("snapshot view changed mid-read")
595						}
596					}
597					snap.Close()
598				}
599			}()
600		}
601	
602		var writerWg sync.WaitGroup
603		writerWg.Add(1)
604		go func() {
605			defer writerWg.Done()
606			for i := 1; i <= 500; i++ {
607				if err := s.Put("a", []byte(strconv.Itoa(i))); err != nil {
608					return // store may close under us
609				}
610			}
611		}()
612	
613		writerWg.Wait()
614		if err := s.Close(); err != nil {
615			t.Fatal(err)
616		}
617		readerWg.Wait()
618	
619		if sawClosed.Load() == 0 {
620			t.Fatal("no reader observed fs.ErrClosed after close")
621		}
622	
623		// Snapshots already handed out survive close; verify one explicitly.
624		// (Acquire-then-close ordering.)
625		s2 := openStore(t, tempDir(t))
626		if err := s2.Put("k", []byte("v")); err != nil {
627			t.Fatal(err)
628		}
629		snap, err := s2.Snapshot()
630		if err != nil {
631			t.Fatal(err)
632		}
633		if err := s2.Put("k", []byte("v2")); err != nil {
634			t.Fatal(err)
635		}
636		if err := s2.Close(); err != nil {
637			t.Fatal(err)
638		}
639		if got, ok := snap.Get("k"); !ok || string(got) != "v" {
640			t.Fatalf("snapshot broken by concurrent close: %q %v", got, ok)
641		}
642		if err := snap.Close(); err != nil {
643			t.Fatal(err)
644		}
645	}
