18	func keysOf(pairs []KVPair) []string {
19		ks := make([]string, len(pairs))
20		for i, p := range pairs {
21			ks[i] = p.Key
22		}
23		return ks
24	}
25	
26	func TestStoreScanOrderedRange(t *testing.T) {
27		s := openStore(t, tempDir(t))
28	
29		// Insert out of order, including binary keys, to prove byte ordering.
30		for _, k := range []string{"c", "a", "b", "a1", "a\x00", "a\xff", "\x01", "ab"} {
31			if err := s.Put(k, []byte("v-"+k)); err != nil {
32				t.Fatal(err)
33			}
34		}
35		if err := s.Put("deleted", []byte("x")); err != nil {
36			t.Fatal(err)
37		}
38		if err := s.Delete("deleted"); err != nil {
39			t.Fatal(err)
40		}
41		if err := s.Put("empty", nil); err != nil { // empty value still a hit
42			t.Fatal(err)
43		}
44	
45		pairs, err := s.Scan(Range{}, 0)
46		if err != nil {
47			t.Fatal(err)
48		}
49		want := []string{"\x01", "a", "a\x00", "a1", "ab", "a\xff", "b", "c", "empty"}
50		if got := keysOf(pairs); !sliceEq(got, want) {
51			t.Fatalf("full scan order:\n got=%q\nwant=%q", got, want)
52		}
53		// Empty-value key is present with a zero-length value (nil, like Get).
54		foundEmpty := false
55		for _, p := range pairs {
56			if p.Key == "empty" {
57				foundEmpty = true
58				if len(p.Value) != 0 {
59					t.Fatalf("empty-value key has non-empty value: %v", p.Value)
60				}
61			}
62		}
63		if !foundEmpty {
64			t.Fatal("empty-value key missing from scan")
65		}
66		// Deleted and never-written keys absent; empty key can never exist.
67		for _, bad := range []string{"deleted", "never", ""} {
68			if i := sort.SearchStrings(keysOf(pairs), bad); i < len(pairs) && pairs[i].Key == bad {
69				t.Fatalf("scan included %q", bad)
70			}
71		}
72	
73		// Half-open interval ["a","b"): includes a, a\x00, a\xff, a1, ab.
74		pairs, err = s.Scan(Range{Start: "a", End: "b"}, 0)
75		if err != nil {
76			t.Fatal(err)
77		}
78		if got := keysOf(pairs); !sliceEq(got, want[1:6]) {
79			t.Fatalf("range [a,b): %q want %q", got, want[1:6])
80		}
81	
82		// Open-ended Start.
83		pairs, err = s.Scan(Range{Start: "b"}, 0)
84		if err != nil {
85			t.Fatal(err)
86		}
87		if got := keysOf(pairs); !sliceEq(got, []string{"b", "c", "empty"}) {
88			t.Fatalf("range [b,): %q", got)
89		}
90	
91		// End-bounded: [, "a1") excludes "a1" and everything byte-above it.
92		pairs, err = s.Scan(Range{End: "a1"}, 0)
93		if err != nil {
94			t.Fatal(err)
95		}
96		if got := keysOf(pairs); !sliceEq(got, []string{"\x01", "a", "a\x00"}) {
97			t.Fatalf("range [,a1): %q", got)
98		}
99	
100		// Limit truncates in order; a non-positive limit means everything.
101		pairs, err = s.Scan(Range{}, 3)
102		if err != nil {
103			t.Fatal(err)
104		}
105		if len(pairs) != 3 {
106			t.Fatalf("limit 3 got %d pairs", len(pairs))
107		}
108		if got := keysOf(pairs); !sliceEq(got, want[:3]) {
109			t.Fatalf("limited scan: %q", got)
110		}
111	}
112	
113	func TestScanReversedAndNonmatchingAreEmpty(t *testing.T) {
114		s := openStore(t, tempDir(t))
115		if err := s.Put("m", []byte("1")); err != nil {
116			t.Fatal(err)
117		}
118		for _, r := range []Range{
119			{Start: "z", End: "a"}, // reversed
120			{Start: "m", End: "m"}, // zero-width
121			{Start: "n", End: "z"}, // in order but nothing there
122		} {
123			pairs, err := s.Scan(r, 0)
124			if err != nil {
125				t.Fatalf("range %v: unexpected err %v", r, err)
126			}
127			if len(pairs) != 0 {
128				t.Fatalf("range %v returned partial data: %q", r, pairs)
129			}
130		}
131	
132		// Prefix that matches nothing: empty, no error.
133		pairs, err := s.ScanPrefix("zzz", 0)
134		if err != nil {
135			t.Fatal(err)
136		}
137		if len(pairs) != 0 {
138			t.Fatalf("nonmatching prefix: %q", pairs)
139		}
140	}
141	
142	func TestScanPrefixBoundaries(t *testing.T) {
143		s := openStore(t, tempDir(t))
144		keys := []string{"a", "ab", "abc", "b", "a\xff", "a\xffz", "b\x00"}
145		for _, k := range keys {
146			if err := s.Put(k, []byte(k)); err != nil {
147				t.Fatal(err)
148			}
149		}
150	
151		pairs, err := s.ScanPrefix("a", 0)
152		if err != nil {
153			t.Fatal(err)
154		}
155		if got := keysOf(pairs); !sliceEq(got, []string{"a", "ab", "abc", "a\xff", "a\xffz"}) {
156			t.Fatalf("prefix a: %q", got)
157		}
158	
159		// Trailing 0xFF rolls the bound: "a\xff" covers a\xff and a\xffz, ends at "b".
160		pairs, err = s.ScanPrefix("a\xff", 0)
161		if err != nil {
162			t.Fatal(err)
163		}
164		if got := keysOf(pairs); !sliceEq(got, []string{"a\xff", "a\xffz"}) {
165			t.Fatalf("prefix a\\xff: %q", got)
166		}
167	
168		// All-0xFF prefix is effectively unbounded past it.
169		if err := s.Put("\xff\x01", []byte("x")); err != nil {
170			t.Fatal(err)
171		}
172		pairs, err = s.ScanPrefix("\xff", 0)
173		if err != nil {
174			t.Fatal(err)
175		}
176		if got := keysOf(pairs); !sliceEq(got, []string{"\xff\x01"}) {
177			t.Fatalf("prefix \\xff: %q", got)
178		}
179	
180		// Empty prefix matches everything.
181		pairs, err = s.ScanPrefix("", 0)
182		if err != nil {
183			t.Fatal(err)
184		}
185		if len(pairs) != len(keys)+1 {
186			t.Fatalf("empty prefix matched %d, want %d", len(pairs), len(keys)+1)
187		}
188	
189		// Returned values are byte-correct copies.
190		pairs, _ = s.ScanPrefix("ab", 0)
191		if len(pairs) != 2 || pairs[0].Key != "ab" || string(pairs[0].Value) != "ab" {
192			t.Fatalf("prefix ab values: %+v", pairs)
193		}
194	}
195	
196	func TestScanOnClosedStore(t *testing.T) {
197		s := openStore(t, tempDir(t))
198		if err := s.Put("k", []byte("v")); err != nil {
199			t.Fatal(err)
200		}
201		if err := s.Close(); err != nil {
202			t.Fatal(err)
203		}
204		if _, err := s.Scan(Range{}, 0); !errors.Is(err, fs.ErrClosed) {
205			t.Fatalf("scan closed store: %v", err)
206		}
207		if _, err := s.ScanPrefix("k", 0); !errors.Is(err, fs.ErrClosed) {
208			t.Fatalf("scanprefix closed store: %v", err)
209		}
210		if _, err := s.OpenCursor(Range{}); !errors.Is(err, fs.ErrClosed) {
211			t.Fatalf("opencursor closed store: %v", err)
212		}
213		if _, err := s.OpenCursorPrefix("k"); !errors.Is(err, fs.ErrClosed) {
214			t.Fatalf("opencursorprefix closed store: %v", err)
215		}
216	}
217	
218	func TestSnapshotScanFixedView(t *testing.T) {
219		s := openStore(t, tempDir(t))
220		if err := s.Put("a", []byte("1")); err != nil {
221			t.Fatal(err)
222		}
223		if err := s.Put("b", []byte("2")); err != nil {
224			t.Fatal(err)
225		}
226		snap, err := s.Snapshot()
227		if err != nil {
228			t.Fatal(err)
229		}
230	
231		if err := s.Put("a", []byte("9")); err != nil {
232			t.Fatal(err)
233		}
234		if err := s.Put("c", []byte("3")); err != nil {
235			t.Fatal(err)
236		}
237		if err := s.Delete("b"); err != nil {
238			t.Fatal(err)
239		}
240	
241		pairs, err := snap.Scan(Range{}, 0)
242		if err != nil {
243			t.Fatal(err)
244		}
245		if got := keysOf(pairs); !sliceEq(got, []string{"a", "b"}) {
246			t.Fatalf("snapshot scan: %q", got)
247		}
248		if string(pairs[0].Value) != "1" || string(pairs[1].Value) != "2" {
249			t.Fatalf("snapshot scan values: %q %q", pairs[0].Value, pairs[1].Value)
250		}
251		pairs, err = snap.ScanPrefix("a", 0)
252		if err != nil {
253			t.Fatal(err)
254		}
255		if len(pairs) != 1 || string(pairs[0].Value) != "1" {
256			t.Fatalf("snapshot prefix: %+v", pairs)
257		}
258	
259		// Closed snapshot: scans are empty misses, never errors.
260		if err := snap.Close(); err != nil {
261			t.Fatal(err)
262		}
263		if pairs, err := snap.Scan(Range{}, 0); err != nil || len(pairs) != 0 {
264			t.Fatalf("closed snapshot scan: %v %v", pairs, err)
265		}
266		if pairs, err := snap.ScanPrefix("", 0); err != nil || len(pairs) != 0 {
267			t.Fatalf("closed snapshot prefix: %v %v", pairs, err)
268		}
269		if cur, err := snap.OpenCursor(Range{}); err != nil {
270			t.Fatalf("cursor on closed snapshot: %v", err)
271		} else {
272			if p, err := cur.Page(0, 10); err != nil || len(p) != 0 {
273				t.Fatalf("page on closed-snapshot cursor: %v %v", p, err)
274			}
275			if err := cur.Close(); err != nil {
276				t.Fatal(err)
277			}
278		}
279	}
280	
281	func drainCursor(t *testing.T, c *Cursor, pageSize int) []KVPair {
282		t.Helper()
283		var all []KVPair
284		off := 0
285		for {
286			page, err := c.Page(off, pageSize)
287			if err != nil {
288				t.Fatalf("page off=%d: %v", off, err)
289			}
290			all = append(all, page...)
291			if len(page) < pageSize {
292				// One more confirmation page at the exact end offset: empty, nil.
293				end, err := c.Page(off+len(page), 1)
294				if err != nil || len(end) != 0 {
295					t.Fatalf("end page: %v %v", end, err)
296				}
297				return all
298			}
299			off += len(page)
300		}
301	}
302	
303	func TestCursorPaginationByteIdentical(t *testing.T) {
304		s := openStore(t, tempDir(t))
305		const n = 25
306		for i := 0; i < n; i++ {
307			k := fmt.Sprintf("k%03d", i)
308			if err := s.Put(k, []byte(strings.Repeat("v", i+1))); err != nil {
309				t.Fatal(err)
310			}
311		}
312		expected, err := s.Scan(Range{}, 0)
313		if err != nil {
314			t.Fatal(err)
315		}
316	
317		c, err := s.OpenCursor(Range{})
318		if err != nil {
319			t.Fatal(err)
320		}
321	
322		// Mutate the world while paging: overwrites, deletes, new keys, new
323		// snapshots and compactions must not change the cursor's sequence.
324		var wg sync.WaitGroup
325		wg.Add(1)
326		go func() {
327			defer wg.Done()
328			for i := 0; i < n; i++ {
329				s.Put(fmt.Sprintf("k%03d", i%n), []byte("changed"))
330				if i%3 == 0 {
331					s.Delete(fmt.Sprintf("k%03d", i))
332				}
333				s.Put(fmt.Sprintf("new%03d", i), []byte("x"))
334				s.Compact()
335				snap, _ := s.Snapshot()
336				snap.Close()
337			}
338		}()
339	
340		var all []KVPair
341		off := 0
342		for {
343			page, perr := c.Page(off, 7)
344			if perr != nil {
345				t.Fatalf("page off=%d: %v", off, perr)
346			}
347			all = append(all, page...)
348			off += len(page)
349			if len(page) < 7 {
350				break
351			}
352		}
353		wg.Wait()
354	
355		if len(all) != len(expected) {
356			t.Fatalf("paged %d pairs, want %d", len(all), len(expected))
357		}
358		for i := range expected {
359			if all[i].Key != expected[i].Key || !bytes.Equal(all[i].Value, expected[i].Value) {
360				t.Fatalf("page %d differs: got %q=%q want %q=%q",
361					i, all[i].Key, all[i].Value, expected[i].Key, expected[i].Value)
362			}
363		}
364		if err := c.Close(); err != nil {
365			t.Fatal(err)
366		}
367	}
368	
369	func TestCursorInvalidArguments(t *testing.T) {
370		s := openStore(t, tempDir(t))
371		for _, k := range []string{"a", "b", "c"} {
372			if err := s.Put(k, []byte(k)); err != nil {
373				t.Fatal(err)
374			}
375		}
376		c, err := s.OpenCursor(Range{})
377		if err != nil {
378			t.Fatal(err)
379		}
380		for _, tc := range []struct {
381			name       string
382			off, limit int
383		}{
384			{"zero limit", 0, 0},
385			{"negative limit", 0, -1},
386			{"negative offset", -1, 1},
387			{"offset past end", 4, 1},
388			{"far past end", 100, 1},
389		} {
390			if _, err := c.Page(tc.off, tc.limit); !errors.Is(err, fs.ErrInvalid) {
391				t.Fatalf("%s: err=%v want fs.ErrInvalid", tc.name, err)
392			}
393		}
394		// A failed call changes nothing: the sequence still reads whole.
395		all := drainCursor(t, c, 2)
396		if got := keysOf(all); !sliceEq(got, []string{"a", "b", "c"}) {
397			t.Fatalf("cursor after invalid args: %q", got)
398		}
399	
400		// Re-reading an earlier in-range offset is allowed and gives the same
401		// bytes; the canonical forward walk still has no dup or gap.
402		p, err := c.Page(1, 1)
403		if err != nil || len(p) != 1 || p[0].Key != "b" || string(p[0].Value) != "b" {
404			t.Fatalf("re-read offset 1: %+v err=%v", p, err)
405		}
406	
407		if err := c.Close(); err != nil {
408			t.Fatal(err)
409		}
410		// Closed: reads are empty, no error; invalid limit is also just empty.
411		if p, err := c.Page(0, 1); err != nil || len(p) != 0 {
412			t.Fatalf("page closed cursor: %v %v", p, err)
413		}
414		if p, err := c.Page(0, -9); err != nil || len(p) != 0 {
415			t.Fatalf("bad page closed cursor: %v %v", p, err)
416		}
417		if err := c.Close(); err != nil { // idempotent
418			t.Fatalf("double close: %v", err)
419		}
420	}
421	
422	func TestCursorBoundsAndReversed(t *testing.T) {
423		s := openStore(t, tempDir(t))
424		for _, k := range []string{"a", "aa", "ab", "b"} {
425			if err := s.Put(k, []byte(k)); err != nil {
426				t.Fatal(err)
