671	func TestConcurrentScansAndCursorCloses(t *testing.T) {
672		s := openStore(t, tempDir(t))
673		for i := 0; i < 50; i++ {
674			if err := s.Put(fmt.Sprintf("k%03d", i), []byte(fmt.Sprintf("%d", i))); err != nil {
675				t.Fatal(err)
676			}
677		}
678	
679		var wg sync.WaitGroup
680		stop := make(chan struct{})
681	
682		// Scanners hammer both views while writers mutate.
683		for r := 0; r < 4; r++ {
684			wg.Add(1)
685			go func() {
686				defer wg.Done()
687				for {
688					select {
689					case <-stop:
690						return
691					default:
692					}
693					pairs, err := s.Scan(Range{}, 0)
694					if err != nil {
695						if errors.Is(err, fs.ErrClosed) {
696							return
697						}
698						t.Errorf("scan: %v", err)
699						return
700					}
701					keys := keysOf(pairs)
702					if !sort.StringsAreSorted(keys) {
703						t.Errorf("scan not sorted")
704						return
705					}
706				}
707			}()
708		}
709	
710		// Cursors opened, paged from many goroutines, and closed repeatedly.
711		for r := 0; r < 4; r++ {
712			wg.Add(1)
713			go func() {
714				defer wg.Done()
715				for {
716					select {
717					case <-stop:
718						return
719					default:
720					}
721					c, err := s.OpenCursor(Range{})
722					if err != nil {
723						if errors.Is(err, fs.ErrClosed) {
724							return
725						}
726						t.Errorf("open cursor: %v", err)
727						return
728					}
729					var cwg sync.WaitGroup
730					for p := 0; p < 3; p++ {
731						cwg.Add(1)
732						go func(seed int) {
733							defer cwg.Done()
734							off := 0
735							for off < 60 {
736								page, err := c.Page(off, 5)
737								if err != nil {
738									if errors.Is(err, fs.ErrInvalid) {
739										return // another goroutine passed a different offset race
740									}
741									return
742								}
743								if len(page) == 0 {
744									return
745								}
746								off += len(page)
747							}
748						}(r)
749					}
750					cwg.Wait()
751					if err := c.Close(); err != nil {
752						t.Errorf("close: %v", err)
753						return
754					}
755					if err := c.Close(); err != nil { // duplicate close queues, nil
756						t.Errorf("double close: %v", err)
757						return
758					}
759				}
760			}()
761		}
762	
763		for w := 0; w < 2; w++ {
764			wg.Add(1)
765			go func(w int) {
766				defer wg.Done()
767				for i := 0; i < 200; i++ {
768					if err := s.Put(fmt.Sprintf("k%03d", i%50), []byte("x")); err != nil {
769						return
770					}
771					if i%25 == 0 {
772						s.Compact()
773					}
774				}
775			}(w)
776		}
777	
778		// One cursor stays open the whole time: its in-flight paging must remain
779		// unaffected by all of the above, including repeated close attempts of
780		// *other* cursors.
781		steady, err := s.OpenCursor(Range{})
782		if err != nil {
783			t.Fatal(err)
784		}
785		expected, _ := steady.Page(0, 1000)
786		for i := 0; i < 20; i++ {
787			got, err := steady.Page(0, 1000)
788			if err != nil {
789				t.Fatalf("steady cursor: %v", err)
790			}
791			if len(got) != len(expected) {
792				t.Fatalf("steady cursor length changed: %d vs %d", len(got), len(expected))
793			}
794			for j := range expected {
795				if got[j].Key != expected[j].Key || !bytes.Equal(got[j].Value, expected[j].Value) {
796					t.Fatalf("steady cursor changed at %d", j)
797				}
798			}
799		}
800	
801		close(stop)
802		wg.Wait()
803		if err := steady.Close(); err != nil {
804			t.Fatal(err)
805		}
806	}
