// runCommitLeader is the group-commit loop. It is entered holding s.mu (with
// the caller's own req already queued) and runs until the queue is fully
// drained, looping to pick up batches that arrive while a group syncs. Every
// iteration performs at most one flush and one fsync for all batches the
// arrival window gathered.
func (s *Store) runCommitLeader() {
	for {
		// Arrival window: concurrent callers queue while the lock is free.
		// Production yields the scheduler once; a test hook can block here
		// until a deterministic set of batches has queued.
		s.mu.Unlock()
		if s.groupYield != nil {
			s.groupYield()
		} else {
			runtime.Gosched()
		}
		s.mu.Lock()

		group := s.queue
		s.queue = nil

		// Project each batch's last-wins effect against the committed view
		// plus earlier batches in this same group, so a delete of a key
		// created by an earlier queued batch is kept, while no-op deletes
		// persist nothing (matching single Delete semantics).
		proj := make(map[string]bool)
		for k, n := range *s.current.Load() {
			proj[k] = n.present
		}
		for _, req := range group {
			req.eff, proj = effectiveOps(req.raw, proj)
		}

		// Encode the whole group back to back, flush once, then sync once
		// with no state lock held: reads never block here.
		s.mu.Unlock()
		s.walMu.Lock()
		w := s.wal
		start := w.committed()
		encErr := encodeGroup(w, group)
		var syncErr error
		var f = w.f
		if encErr == nil {
			if err := w.w.Flush(); err != nil {
				encErr = err
			}
		}
		end := w.writePos
		s.walMu.Unlock()
		if encErr == nil {
			syncErr = f.Sync()
		}
		failErr := encErr
		if failErr == nil {
			failErr = syncErr
		}

		s.walMu.Lock()
		if failErr == nil {
			w.committedSize = end
		} else {
			// Strip this group's bytes so surviving batches append at the
			// old committed boundary and nothing half-encoded remains.
			if err := w.rollbackTo(start); err != nil {
				failErr = errors.Join(failErr, err)
				s.walMu.Unlock()
				s.mu.Lock()
				s.closed.Store(true) // a wedged log cannot be trusted
				for _, r := range group {
					r.done <- failErr
				}
				s.leaderBusy = false
				s.idleCond.Broadcast()
				s.mu.Unlock()
				return
			}
		}
		s.walMu.Unlock()

		s.mu.Lock()
		if failErr != nil {
			// Atomic: no view was touched, so every batch is fully absent.
			for _, r := range group {
				r.done <- failErr
			}
		} else {
			// Publish one view per batch in commit order, so each batch is a
			// single all-or-nothing point observable through snapshots.
			for _, r := range group {
				if len(r.eff) > 0 {
					next := s.deriveView()
					for _, op := range r.eff {
						if op.put {
							next[op.key] = &node{value: op.value, present: true, seq: r.seq, older: next[op.key]}
						} else {
							next[op.key] = &node{present: false, seq: r.seq, older: next[op.key]}
						}
					}
					s.current.Store(&next)
				}
				r.done <- nil
			}
		}

		if len(s.queue) == 0 {
			s.leaderBusy = false
			s.idleCond.Broadcast()
			s.mu.Unlock()
			return
		}
	}
}

