					if errors.Is(err, fs.ErrClosed) {
						return
					}
					t.Errorf("open cursor: %v", err)
					return
				}
				off := 0
				for {
					page, err := c.Page(off, 16)
					if err != nil {
						break
					}
					off += len(page)
					if len(page) < 16 {
						break
					}
				}
				c.Close()
			}
		}()
	}

	// Let it churn, then stop and settle with one final compaction.
	runtime.Gosched()
	close(stop)
	wg.Wait()
	if err := s.Compact(); err != nil {
		t.Fatalf("final compact: %v", err)
	}
}
